From 3bfae8dbebbd7c979922b7296522ec444dd6fae9 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 28 Nov 2026 12:49:36 +0100
Subject: [PATCH] applets/quicklaunch: hide launcher editing when widgets are
 locked

Locking widgets only stopped dragging launchers around, while the context
menus still offered to add, edit and remove launchers and the Delete key
still removed them. Those actions are now hidden or ignored when locked.

BUG: 291146
---
 applets/quicklaunch/IconItem.qml | 9 +++++++--
 applets/quicklaunch/main.qml     | 1 +
 2 files changed, 8 insertions(+), 2 deletions(-)

diff --git a/applets/quicklaunch/IconItem.qml b/applets/quicklaunch/IconItem.qml
index ab6d8aba3..64d44e670 100644
--- a/applets/quicklaunch/IconItem.qml
+++ b/applets/quicklaunch/IconItem.qml
@@ -53,8 +53,10 @@ Item {
             break;
         case Qt.Key_Backspace:
         case Qt.Key_Delete:
-            removeLauncher();
-            event.accepted = true;
+            if (!Plasmoid.immutable) {
+                removeLauncher();
+                event.accepted = true;
+            }
             break;
         }

@@ -266,18 +268,21 @@ Item {

                 PlasmaExtras.MenuItem {
                     text: i18nc("@action:inmenu", "Add Launcher…")
+                    visible: !Plasmoid.immutable
                     icon: "list-add"
                     onClicked: iconItem.addLauncher()
                 }

                 PlasmaExtras.MenuItem {
                     text: i18nc("@action:inmenu", "Edit Launcher…")
+                    visible: !Plasmoid.immutable
                     icon: "document-edit"
                     onClicked: iconItem.editLauncher()
                 }

                 PlasmaExtras.MenuItem {
                     text: i18nc("@action:inmenu", "Remove Launcher")
+                    visible: !Plasmoid.immutable
                     icon: "list-remove"
                     onClicked: iconItem.removeLauncher()
                 }
diff --git a/applets/quicklaunch/main.qml b/applets/quicklaunch/main.qml
index 012b52556..aa27754c8 100644
--- a/applets/quicklaunch/main.qml
+++ b/applets/quicklaunch/main.qml
@@ -340,6 +340,7 @@ PlasmoidItem {
         PlasmaCore.Action {
             text: i18nc("@action", "Add Launcher…")
             icon.name: "list-add"
+            visible: !Plasmoid.immutable
             onTriggered: logic.addLauncher()
         }
     ]
-- 
